css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .rule { position: absolute; background: color-mix(in srgb, var(--accent) 55%, transparent); border-radius: 3px; }
.loader .rule:nth-of-type(1) { left: 32%; top: 4%; width: 3%; height: 92%; }
.loader .rule:nth-of-type(2) { left: 65%; top: 4%; width: 3%; height: 92%; }
.loader .rule:nth-of-type(3) { top: 32%; left: 4%; height: 3%; width: 92%; }
.loader .rule:nth-of-type(4) { top: 65%; left: 4%; height: 3%; width: 92%; }
.loader span { position: absolute; width: 20%; height: 20%; border-radius: 50%; box-shadow: inset 0 0 0 4px var(--accent); transform: scale(0); animation: ttt-mark calc(var(--loader-speed) * 3.6) ease-out infinite; }
.loader span:nth-of-type(1) { left: 7%; top: 7%; border-radius: 3px; box-shadow: none; background: linear-gradient(45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%), linear-gradient(-45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%); }
.loader span:nth-of-type(2) { left: 40%; top: 40%; animation-delay: calc(var(--loader-speed) * .4); }
.loader span:nth-of-type(3) { left: 73%; top: 7%; border-radius: 3px; box-shadow: none; background: linear-gradient(45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%), linear-gradient(-45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%); animation-delay: calc(var(--loader-speed) * .8); }
.loader span:nth-of-type(4) { left: 7%; top: 73%; animation-delay: calc(var(--loader-speed) * 1.2); }
.loader span:nth-of-type(5) { left: 40%; top: 7%; border-radius: 3px; box-shadow: none; background: linear-gradient(45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%), linear-gradient(-45deg, transparent 44%, var(--accent-2) 44% 56%, transparent 56%); animation-delay: calc(var(--loader-speed) * 1.6); }
.loader .win { position: absolute; left: 10%; top: 15%; width: 80%; height: 4%; border-radius: 3px; background: var(--accent-2); transform-origin: 0 50%; transform: scaleX(0); animation: ttt-win calc(var(--loader-speed) * 3.6) ease-out infinite; }
@keyframes ttt-mark { 0%, 6% { transform: scale(0); opacity: 0; } 16%, 76% { transform: scale(1); opacity: 1; } 88%, 100% { transform: scale(0); opacity: 0; } }
@keyframes ttt-win { 0%, 52% { transform: scaleX(0); opacity: 0; } 62%, 78% { transform: scaleX(1); opacity: 1; } 88%, 100% { transform: scaleX(0); opacity: 0; } }
